```csharp
using System;

class Program
{
    static void Main()
    {
        int[] array = { 1, 2, 3, 4, 5, 2, 3, 4 };
        int itemToRemove = 2;

        int[] result = RemoveOccurrences(array, itemToRemove);

        Console.WriteLine("Array after removing all occurrences of " + itemToRemove + ":");
        foreach (int num in result)
        {
            Console.WriteLine(num);
        }
    }

    static int[] RemoveOccurrences(int[] array, int item)
    {
        int[] result = new int[array.Length];
        int index = 0;

        for (int i = 0; i < array.Length; i++)
        {
            if (array[i] != item)
            {
                result[index++] = array[i];
            }
        }

        return result;
    }
}
